// Import the Verus prelude so that `requires!`, `ensures!`, `invariant!`, etc. become available.
use verus::prelude::*;

verus! {
    /// Given
    ///   - `indices`: a non‐empty vector of u8 indices,
    ///   - `choices`: a non‐empty matrix (vector of rows), where each row has the same length
    ///                as `indices.len()`, and
    ///   - for each i, `indices[i] as usize < choices.len()`
    ///
    /// returns a new vector `res` of length `indices.len()`
    /// such that
    ///   res[i] == choices[ indices[i] as usize ][ i ].
    pub fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64> {
        // Preconditions
        requires(!indices.is_empty());
        requires(!choices.is_empty());
        // Every row has length equal to the length of `indices`.
        requires(forall(|j: usize| j < choices.len() ==> choices[j].len() == indices.len()));
        // Every index is a valid row selector
        requires(forall(|i: usize| i < indices.len() ==> (indices[i] as usize) < choices.len()));

        // Postconditions
        ensures(|res: Vec<f64>| res.len() == indices.len());
        ensures(|res: Vec<f64>| forall(|i: usize| i < res.len() ==>
            res[i] == choices[indices[i] as usize][i]
        ));

        // Build the result vector in a loop
        let mut res: Vec<f64> = Vec::new();
        let mut i: usize = 0;
        while i < indices.len() {
            // Loop invariants
            invariant(i <= indices.len());
            invariant(res.len() == i);
            // So far, for all k < i, we have already set res[k] correctly.
            invariant(forall(|k: usize| k < i ==>
                res[k] == choices[indices[k] as usize][k]
            ));
            // Well‐foundedness for termination
            decreases(indices.len() - i);

            // Compute the next element:
            let row: usize = indices[i] as usize;
            // By the preconditions, row < choices.len() and each row has length indices.len(),
            // so choices[row][i] is safe.
            let value: f64 = choices[row][i];
            res.push(value);

            i += 1;
        }

        // At this point, i == indices.len() and res.len() == indices.len(),
        // and by the invariant the content is correct.
        res
    }
}